create extension if not exists pgcrypto;
create table if not exists restaurants(id uuid primary key default gen_random_uuid(),name text not null,address text,timezone text not null default 'America/New_York',hours jsonb not null default '{}'::jsonb);
create table if not exists menu_categories(id uuid primary key default gen_random_uuid(),restaurant_id uuid not null references restaurants(id),name text not null,unique(restaurant_id,name));
create table if not exists menu_items(id uuid primary key default gen_random_uuid(),restaurant_id uuid not null references restaurants(id),category_id uuid not null references menu_categories(id),sku text not null unique,name text not null,price_cents integer not null check(price_cents>=0),available boolean not null default true,active boolean not null default true,spice_enabled boolean not null default false,special_instructions_allowed boolean not null default true,review_note text,source_page integer);
create table if not exists modifier_groups(id uuid primary key default gen_random_uuid(),name text not null,min_select integer not null default 0,max_select integer not null default 1);
create table if not exists modifier_options(id uuid primary key default gen_random_uuid(),group_id uuid not null references modifier_groups(id),name text not null,price_delta_cents integer not null default 0,available boolean not null default true);
create table if not exists menu_item_modifier_groups(item_id uuid not null references menu_items(id),group_id uuid not null references modifier_groups(id),primary key(item_id,group_id));
create table if not exists customers(id uuid primary key default gen_random_uuid(),name text,phone_e164 text);
create table if not exists conversations(id uuid primary key default gen_random_uuid(),customer_id uuid references customers(id),channel text not null check(channel in ('VOICE','WHATSAPP')),provider_session_id text unique,state jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table if not exists carts(id uuid primary key default gen_random_uuid(),conversation_id uuid references conversations(id),status text not null default 'DRAFT',version integer not null default 1,created_at timestamptz not null default now());
create table if not exists cart_items(id uuid primary key default gen_random_uuid(),cart_id uuid not null references carts(id),menu_item_id uuid not null references menu_items(id),quantity integer not null check(quantity>0),selected_options jsonb not null default '[]'::jsonb,spice_level text check(spice_level in ('MILD','MEDIUM','SPICY')),special_instructions text);
create table if not exists orders(id uuid primary key default gen_random_uuid(),restaurant_id uuid not null references restaurants(id),customer_id uuid references customers(id),cart_id uuid references carts(id),reference text unique not null,idempotency_key text unique not null,channel text not null check(channel in ('VOICE','WHATSAPP')),status text not null default 'PENDING_APPROVAL',subtotal_cents integer not null,tax_cents integer not null,total_cents integer not null,pickup_eta timestamptz,accepted_by text,created_at timestamptz not null default now());
create table if not exists order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references orders(id),item_name_snapshot text not null,unit_price_cents integer not null,quantity integer not null,modifiers_snapshot jsonb not null default '[]'::jsonb,special_instructions text);
create table if not exists notifications(id uuid primary key default gen_random_uuid(),order_id uuid not null references orders(id),channel text not null,recipient text,provider_message_id text,status text not null default 'QUEUED',attempts integer not null default 0);
create table if not exists webhook_events(id uuid primary key default gen_random_uuid(),provider text not null,provider_event_id text not null,payload_hash text,processed_at timestamptz,unique(provider,provider_event_id));
create table if not exists audit_events(id uuid primary key default gen_random_uuid(),order_id uuid references orders(id),actor text,action text not null,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());